[Flags]
public enum ExecutionOptions
{
    /// <summary>
    /// Just accumulate the state
    /// </summary>
    None = 0,
    /// <summary>
    /// Commit the state after execution
    /// </summary>
    Commit = 1,
    /// <summary>
    /// Restore state after execution
    /// </summary>
    Restore = 2,
    /// <summary>
    /// Skip potential fail checks
    /// </summary>
    SkipValidation = 4,
    /// <summary>
    /// Marker option used by state pre-warmer
    /// </summary>
    Warmup = 8,
    /// <summary>
    /// Accumulate state without committing or restoring (block-building mode)
    /// </summary>
    BuildUp = 16,
    /// <summary>
    /// Skip potential fail checks and commit state after execution
    /// </summary>
    SkipValidationAndCommit = Commit | SkipValidation,
    /// <summary>
    /// Commit and later restore state also skip validation, use for CallAndRestore
    /// </summary>
    CommitAndRestore = Commit | Restore | SkipValidation
}

public TransactionResult Process(Transaction transaction, ITxTracer txTracer, ExecutionOptions options)
{
    if (options == ExecutionOptions.BuildUp)
    {
        WorldState.TakeSnapshot(true);
    }

    return ExecuteCore(transaction, txTracer, options);
}

private TransactionResult ExecuteCore(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
{
    if (Logger.IsTrace)
        Logger.Trace($"Executing tx {tx.Hash}");
    // Warmup keeps real fee/nonce semantics, so it must not route to the system processor.
    if (SystemTransactionRoutingKernel.UseSystemProcessor(tx.IsSystem(), opts))
    {
        return GetOrCreateSystemTransactionProcessor().Execute(tx, tracer, opts);
    }

    TransactionResult result = Execute(tx, tracer, opts);
    if (Logger.IsTrace)
        Logger.Trace($"Tx {tx.Hash} was executed, {result}");
    return result;
}

protected virtual TransactionResult Execute(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
{
    BlockHeader header = VirtualMachine.BlockExecutionContext.Header;
    IReleaseSpec spec = GetSpec(header);
    RecoverSenderBeforeIntrinsicGas(tx, spec);
    IntrinsicGas<TGasPolicy> intrinsicGas = CalculateIntrinsicGas(tx, spec, header.GasLimit);
    return Execute(tx, tracer, opts, header, spec, in intrinsicGas);
}

// EIP-2780 self-transfer pricing depends on the signer, so resolve it before computing intrinsic gas.
private void RecoverSenderBeforeIntrinsicGas(Transaction tx, IReleaseSpec spec)
{
    if (spec.IsEip2780Enabled && tx.IsMessageCall && tx.Signature is not null && (tx.SenderAddress is null || !WorldState.AccountExists(tx.SenderAddress)))
    {
        tx.SenderAddress = Ecdsa.RecoverAddress(tx, !spec.ValidateChainId);
    }
}

public void CreateAccount(Address address, in UInt256 balance, in ulong nonce = default)
{
    DebugGuardInScope();
    _stateProvider.CreateAccount(address, balance, nonce);
}

public void CreateAccount(Address address, in UInt256 balance, in ulong nonce = default)
{
    _needsStateRootUpdate = true;
    if (_logger.IsTrace)
        Trace(address, balance, nonce);
    Account account = (balance.IsZero && nonce == 0) ? Account.TotallyEmpty : new Account(nonce, balance);
    PushNew(address, account);
    [MethodImpl(MethodImplOptions.NoInlining)]
    void Trace(Address address, in UInt256 balance, in ulong nonce) => _logger.Trace($"Creating account: {address} with balance {balance.ToHexString(skipLeadingZeros: true)} and nonce {nonce.ToHexString(skipLeadingZeros: true)}");
}

[SkipLocalsInit]
private TransactionResult Execute(Transaction tx, ITxTracer tracer, ExecutionOptions opts, BlockHeader header, IReleaseSpec spec, in IntrinsicGas<TGasPolicy> intrinsicGas)
{
    // restore is CallAndRestore - previous call, we will restore state after the execution
    bool restore = opts.HasFlag(ExecutionOptions.Restore);
    // commit - is for standard execute, we will commit the state after execution
    // !commit - is for build up during block production, we won't commit state after each transaction to support rollbacks
    // we commit only after all block is constructed
    bool commit = opts.HasFlag(ExecutionOptions.Commit) || (!opts.HasFlag(ExecutionOptions.SkipValidation) && !spec.IsEip658Enabled);
    TransactionResult result;
    if (!(result = ValidateStatic(tx, header, spec, opts, in intrinsicGas)))
        return result;
    UInt256 effectiveGasPrice = CalculateEffectiveGasPrice(tx, spec.IsEip1559Enabled, header.BaseFeePerGas, out UInt256 opcodeGasPrice);
    UpdateMetrics(opts, effectiveGasPrice);
    bool deleteCallerAccount = RecoverSenderIfNeeded(tx, spec, opts, effectiveGasPrice);
    if (!(result = ValidateSender(tx, header, spec, tracer, opts)) || !(result = BuyGas(tx, spec, tracer, opts, effectiveGasPrice, out UInt256 premiumPerGas, out UInt256 senderReservedGasPayment, out UInt256 blobBaseFee)) || !(result = IncrementNonce(tx, header, spec, tracer, opts)))
    {
        if (restore)
        {
            WorldState.Reset(resetBlockChanges: false);
        }

        return result;
    }

    Address? simpleTransferRecipient = PrepareSimpleTransferFastPath(tx, spec, out CodeInfo? preloadedCodeInfo, out Address? preloadedDelegationAddress);
    bool commitBeforeExecution = commit && (simpleTransferRecipient is null || restore || tracer.IsTracingState);
    if (commitBeforeExecution)
        WorldState.Commit(spec, tracer.IsTracingState ? tracer : NullTxTracer.Instance, commitRoots: false);
    if (!(result = CalculateAvailableGas(tx, spec, in intrinsicGas, out TGasPolicy gasAvailable)))
        return result;
    if (simpleTransferRecipient is not null)
    {
        return ExecuteSimpleTransfer(tx, header, spec, tracer, opts, restore, commit, deleteCallerAccount, simpleTransferRecipient, in intrinsicGas, gasAvailable, in opcodeGasPrice, in premiumPerGas, in senderReservedGasPayment, in blobBaseFee);
    }

    return ExecuteEvmTransaction(tx, header, spec, tracer, opts, restore, commit, deleteCallerAccount, in intrinsicGas, gasAvailable, in opcodeGasPrice, in premiumPerGas, in senderReservedGasPayment, in blobBaseFee, preloadedCodeInfo, preloadedDelegationAddress);
}

/// <summary>
/// Validates the transaction, in a static manner (i.e. without accessing state/storage).
/// It basically ensures the transaction is well formed (i.e. no null values where not allowed, no overflows, etc).
/// As a part of validating the transaction the premium per gas will be calculated, to save computation this
/// is returned in an out parameter.
/// </summary>
/// <param name = "tx">The transaction to validate</param>
/// <param name = "header">The block containing the transaction. Only BaseFee is being used from the block atm.</param>
/// <param name = "spec">The release spec with which the transaction will be executed</param>
/// <param name = "opts">Options (Flags) to use for execution</param>
/// <param name = "intrinsicGas">Calculated intrinsic gas</param>
/// <returns></returns>
protected virtual TransactionResult ValidateStatic(Transaction tx, BlockHeader header, IReleaseSpec spec, ExecutionOptions opts, in IntrinsicGas<TGasPolicy> intrinsicGas)
{
    bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
    if (tx.SenderAddress is null)
    {
        TraceLogInvalidTx(tx, "SENDER_NOT_SPECIFIED");
        return TransactionResult.SenderNotSpecified;
    }

    // EIP-2681 rejects the transaction nonce that would overflow the sender nonce after inclusion.
    if (validate && tx.Nonce == ulong.MaxValue)
    {
        TraceLogInvalidTx(tx, "NONCE_OVERFLOW");
        return TransactionResult.NonceOverflow;
    }

    if (tx.IsAboveInitCode(spec))
    {
        TraceLogInvalidTx(tx, $"CREATE_TRANSACTION_SIZE_EXCEEDS_MAX_INIT_CODE_SIZE {tx.DataLength} > {spec.MaxInitCodeSize}");
        return TransactionResult.TransactionSizeOverMaxInitCodeSize;
    }

    if (tx.SupportsAuthorizationList)
    {
        ValidationResult noCreation = SetCodeTxValidation.ValidateNoContractCreation(tx);
        if (!noCreation)
        {
            TraceLogInvalidTx(tx, "SETCODE_TX_CREATE");
            return TransactionResult.ErrorType.MalformedTransaction.WithDetail($"{noCreation.Error} (sender {tx.SenderAddress})");
        }

        ValidationResult authList = SetCodeTxValidation.ValidateAuthorizationList(tx);
        if (!authList)
        {
            TraceLogInvalidTx(tx, "EMPTY_AUTHORIZATION_LIST");
            return TransactionResult.ErrorType.MalformedTransaction.WithDetail($"{authList.Error} (sender {tx.SenderAddress})");
        }
    }

    if (spec.IsEip8037Enabled && intrinsicGas.ExceedsCap(Eip7825Constants.DefaultTxGasLimitCap, out ulong execution, out ulong floor))
    {
        TraceLogInvalidTx(tx, $"TX_INTRINSIC_GAS_EXCEEDS_CAP execution={execution} floor={floor} > {Eip7825Constants.DefaultTxGasLimitCap}");
        return TransactionResult.ErrorType.GasLimitBelowIntrinsicGas.WithDetail(TxErrorMessages.TxIntrinsicGasExceedsCap(execution, floor, Eip7825Constants.DefaultTxGasLimitCap));
    }

    TGasPolicy standard = intrinsicGas.Standard;
    TGasPolicy floorGas = intrinsicGas.FloorGas;
    ulong standardGasUsed = TGasPolicy.GetRemainingGas(in standard);
    ulong floorGasUsed = TGasPolicy.GetRemainingGas(in floorGas);
    if (tx.GasLimit < standardGasUsed)
    {
        TraceLogInvalidTx(tx, $"GAS_LIMIT_BELOW_INTRINSIC_GAS {tx.GasLimit} < {standardGasUsed}");
        return TransactionResult.ErrorType.GasLimitBelowIntrinsicGas.WithDetail($"{TxErrorMessages.IntrinsicGasTooLow}: have {tx.GasLimit}, want {standardGasUsed}");
    }

    if (tx.GasLimit < floorGasUsed)
    {
        TraceLogInvalidTx(tx, $"GAS_LIMIT_BELOW_FLOOR_DATA_GAS {tx.GasLimit} < {floorGasUsed}");
        return TransactionResult.ErrorType.GasLimitBelowFloorGas.WithDetail($"{TxErrorMessages.GasBelowFloorDataCost}: have {tx.GasLimit}, want {floorGasUsed}");
    }

    ulong minGasRequired = intrinsicGas.MinRequiredGasLimit;
    return ValidateGas(tx, header, spec, in standard, minGasRequired, validate);
}

protected virtual UInt256 CalculateEffectiveGasPrice(Transaction tx, bool eip1559Enabled, in UInt256 baseFee, out UInt256 opcodeGasPrice)
{
    opcodeGasPrice = tx.CalculateEffectiveGasPrice(eip1559Enabled, in baseFee);
    return opcodeGasPrice;
}

private static void UpdateMetrics(ExecutionOptions opts, UInt256 effectiveGasPrice)
{
    // Block production (BuildUp) is excluded: payload builds run concurrently with block import
    // on the same process-wide gas aggregates, and the gauges describe imported blocks, not candidates.
    if (opts is ExecutionOptions.Commit or ExecutionOptions.None)
    {
        Metrics.UpdateBlockGasPrice(effectiveGasPrice);
    }
}

protected virtual bool RecoverSenderIfNeeded(Transaction tx, IReleaseSpec spec, ExecutionOptions opts, in UInt256 effectiveGasPrice)
{
    bool deleteCallerAccount = false;
    Address? sender = tx.SenderAddress;
    if (sender is null || !WorldState.AccountExists(sender))
    {
        bool commit = opts.HasFlag(ExecutionOptions.Commit) || !spec.IsEip658Enabled;
        bool restore = opts.HasFlag(ExecutionOptions.Restore);
        bool noValidation = opts.HasFlag(ExecutionOptions.SkipValidation);
        if (Logger.IsDebug)
            Logger.Debug($"TX sender account does not exist {sender} - trying to recover it");
        // EIP-2780 message calls were already recovered before intrinsic gas.
        if (tx.Signature is not null && (!spec.IsEip2780Enabled || !tx.IsMessageCall))
            tx.SenderAddress = Ecdsa.RecoverAddress(tx, !spec.ValidateChainId);
        if (sender != tx.SenderAddress)
        {
            if (Logger.IsWarn)
                Logger.Warn($"TX recovery issue fixed - tx was coming with sender {sender} and the now it recovers to {tx.SenderAddress}");
            sender = tx.SenderAddress;
        }
        else
        {
            TraceLogInvalidTx(tx, $"SENDER_ACCOUNT_DOES_NOT_EXIST {sender}");
            if (!commit || noValidation || effectiveGasPrice.IsZero)
            {
                deleteCallerAccount = !commit || restore;
                WorldState.CreateAccount(sender!, in UInt256.Zero);
            }
        }

        if (sender is null)
        {
            ThrowInvalidDataException($"Failed to recover sender address on tx {tx.Hash} when previously recovered sender account did not exist.");
        }
    }

    return deleteCallerAccount;
}

protected virtual TransactionResult ValidateSender(Transaction tx, BlockHeader header, IReleaseSpec spec, ITxTracer tracer, ExecutionOptions opts)
{
    bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
    if (validate && !SkipSenderCodeCheck && WorldState.IsInvalidContractSender(spec, tx.SenderAddress!))
    {
        TraceLogInvalidTx(tx, "SENDER_IS_CONTRACT");
        return TransactionResult.SenderHasDeployedCode;
    }

    return TransactionResult.Ok;
}

protected virtual TransactionResult BuyGas(Transaction tx, IReleaseSpec spec, ITxTracer tracer, ExecutionOptions opts, in UInt256 effectiveGasPrice, out UInt256 premiumPerGas, out UInt256 senderReservedGasPayment, out UInt256 blobBaseFee)
{
    Address? sender = tx.SenderAddress;
    Debug.Assert(sender is not null, "Static transaction validation must resolve the sender before gas is charged.");
    premiumPerGas = UInt256.Zero;
    senderReservedGasPayment = UInt256.Zero;
    blobBaseFee = UInt256.Zero;
    UInt256 balance = WorldState.GetBalance(sender);
    bool validate = ShouldValidateGas(tx, opts);
    BlockHeader header = VirtualMachine.BlockExecutionContext.Header;
    if (validate && !TryCalculatePremiumPerGas(tx, header.BaseFeePerGas, out premiumPerGas))
    {
        TraceLogInvalidTx(tx, "MINER_PREMIUM_IS_NEGATIVE");
        string errorDetail = $"max fee per gas less than block base fee: address {tx.SenderAddress?.ToString(withEip55Checksum: true) ?? "unknown"}, maxFeePerGas: {tx.MaxFeePerGas}, baseFee: {header.BaseFeePerGas}";
        return TransactionResult.ErrorType.MaxFeePerGasBelowBaseFee.WithDetail(errorDetail);
    }

    // mgval = gasLimit * effectiveGasPrice.
    if (UInt256.MultiplyOverflow((UInt256)tx.GasLimit, effectiveGasPrice, out senderReservedGasPayment))
    {
        TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}");
        return RequiredBalanceExceeds256Bits(tx);
    }

    // balanceCheck = gasLimit * MaxFeePerGas (EIP-1559) or mgval — the maximum the sender must hold.
    UInt256 balanceCheck;
    if (spec.IsEip1559Enabled && !tx.IsFree())
    {
        if (UInt256.MultiplyOverflow((UInt256)tx.GasLimit, tx.MaxFeePerGas, out balanceCheck))
        {
            TraceLogInvalidTx(tx, $"INSUFFICIENT_MAX_FEE_PER_GAS_FOR_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}, MAX_FEE_PER_GAS: {tx.MaxFeePerGas}");
            return RequiredBalanceExceeds256Bits(tx);
        }
    }
    else
    {
        balanceCheck = senderReservedGasPayment;
    }

    // Include tx.Value in the balance requirement.
    if (UInt256.AddOverflow(balanceCheck, tx.ValueRef, out balanceCheck))
    {
        TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}");
        return RequiredBalanceExceeds256Bits(tx);
    }

    if (tx.SupportsBlobs)
    {
        UInt256 blobGas = BlobGasCalculator.CalculateBlobGas(tx);
        // Add blob fee cap to balance check.
        if (UInt256.MultiplyOverflow(blobGas, (UInt256)tx.MaxFeePerBlobGas!, out UInt256 maxBlobGasFee) || UInt256.AddOverflow(balanceCheck, maxBlobGasFee, out balanceCheck))
        {
            TraceLogInvalidTx(tx, $"INSUFFICIENT_MAX_FEE_PER_BLOB_GAS_FOR_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}");
            return RequiredBalanceExceeds256Bits(tx);
        }

        // Compute actual blob fee and add to mgval.
        if (!_blobBaseFeeCalculator.TryCalculateBlobFees(header, tx, spec.BlobBaseFeeUpdateFraction, out UInt256 feePerBlobGas, out blobBaseFee))
        {
            TraceLogInvalidTx(tx, $"BLOB_BASE_FEE_OVERFLOW: ({tx.SenderAddress})_BALANCE = {balance}");
            return RequiredBalanceExceeds256Bits(tx);
        }

        if (tx.MaxFeePerBlobGas < feePerBlobGas)
        {
            TraceLogInvalidTx(tx, "INSUFFICIENT_MAX_FEE_PER_BLOB_GAS");
            return TransactionResult.WithDetail(TransactionResult.ErrorType.InsufficientSenderBalance, BlockErrorMessages.InsufficientMaxFeePerBlobGas(tx.SenderAddress, tx.MaxFeePerBlobGas, feePerBlobGas));
        }

        if (UInt256.AddOverflow(senderReservedGasPayment, blobBaseFee, out senderReservedGasPayment))
        {
            TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}");
            return RequiredBalanceExceeds256Bits(tx);
        }
    }

    if (balance < balanceCheck)
    {
        // A warm sender may be funded earlier in the block by another sender's
        // transaction, which per-sender warm groups cannot see; charge best-effort
        // instead of losing that sender's warming entirely.
        if (opts.HasFlag(ExecutionOptions.Warmup))
        {
            UInt256 warmCharge = UInt256.Min(senderReservedGasPayment, balance);
            if (!warmCharge.IsZero)
                WorldState.SubtractFromBalance(sender, warmCharge, spec);
            return TransactionResult.Ok;
        }

        TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {balance}");
        return InsufficientFundsForGas(tx, balance, balanceCheck);
    }

    if (!senderReservedGasPayment.IsZero)
        WorldState.SubtractFromBalance(sender, senderReservedGasPayment, spec);
    return TransactionResult.Ok;
}

protected virtual TransactionResult IncrementNonce(Transaction tx, BlockHeader header, IReleaseSpec spec, ITxTracer tracer, ExecutionOptions opts)
{
    Address? senderAddress = tx.SenderAddress;
    Debug.Assert(senderAddress is not null, "Static transaction validation must resolve the sender before its nonce is updated.");
    bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
    ulong nonce = WorldState.GetNonce(senderAddress);
    if (validate && tx.Nonce != nonce)
    {
        TraceLogInvalidTx(tx, $"WRONG_TRANSACTION_NONCE: {tx.Nonce} (expected {nonce})");
        // Geth core/state_transition.go ErrNonceTooHigh / ErrNonceTooLow.
        string sender = tx.SenderAddress?.ToString(withEip55Checksum: true) ?? "unknown";
        return tx.Nonce > nonce ? TransactionResult.ErrorType.TransactionNonceTooHigh.WithDetail($"nonce too high: address {sender}, tx: {tx.Nonce} state: {nonce}") : TransactionResult.ErrorType.TransactionNonceTooLow.WithDetail($"nonce too low: address {sender}, tx: {tx.Nonce} state: {nonce}");
    }

    ulong newNonce = validate || nonce < ulong.MaxValue ? nonce + 1 : 0;
    WorldState.SetNonce(senderAddress, newNonce);
    return TransactionResult.Ok;
}

public bool TryCalculatePremiumPerGas(in UInt256 baseFeePerGas, out UInt256 premiumPerGas)
{
    bool freeTransaction = tx.IsFree();
    UInt256 feeCap = tx.Supports1559 ? tx.MaxFeePerGas : tx.MaxPriorityFeePerGas;
    if (baseFeePerGas > feeCap)
    {
        premiumPerGas = UInt256.Zero;
        return freeTransaction;
    }

    premiumPerGas = UInt256.Min(tx.MaxPriorityFeePerGas, feeCap - baseFeePerGas);
    return true;
}

public bool TryCalculateBlobFees(BlockHeader header, Transaction transaction, ulong blobGasPriceUpdateFraction, out UInt256 feePerBlobGas, out UInt256 totalBlobBaseFee)
{
    if (!BlobGasCalculator.TryCalculateFeePerBlobGas(header, blobGasPriceUpdateFraction, out feePerBlobGas))
    {
        totalBlobBaseFee = UInt256.Zero;
        return false;
    }

    return BlobGasCalculator.TryCalculateBlobBaseFee(header, transaction, blobGasPriceUpdateFraction, out totalBlobBaseFee);
}

/// <summary>
/// Gets the <c>GAS_PER_BLOB</c> parameter.
/// </summary>
/// <remarks>Defaults to 131072.</remarks>
public const ulong GasPerBlob = 131072;

public void SetNonce(Address address, in ulong nonce)
{
    DebugGuardInScope();
    _stateProvider.SetNonce(address, nonce);
}

// used in EthereumTests
internal void SetNonce(Address address, in ulong nonce)
{
    _needsStateRootUpdate = true;
    Account account = GetThroughCache(address) ?? ThrowNullAccount(address);
    Account changedAccount = account.WithChangedNonce(nonce);
    if (_logger.IsTrace)
        Trace(address, account, changedAccount);
    PushUpdate(address, changedAccount);
    [MethodImpl(MethodImplOptions.NoInlining)]
    void Trace(Address address, Account account, Account changedAccount) => _logger.Trace($"Update {address} N {account.Nonce} -> {changedAccount.Nonce}");
    [DoesNotReturn, StackTraceHidden]
    static Account ThrowNullAccount(Address address) => throw new InvalidOperationException($"Account {address} is null when incrementing nonce");
}
